"""Printed 232–234: perpendicular-bisector and equal-chord source material."""
from math import sin,cos,pi
from math12_reviewed_unit1 import heading,paragraph,page
from math12_reviewed_higher_derivatives import eq,note
from math12_reviewed_conics_intro import ellipse
from math12_native_geometry import geometry,path
def chord_midpoint():
 c=(250,135);r=90
 ps=[(c[0]+r*cos(t*pi/180),c[1]+r*sin(t*pi/180)) for t in [135,35]]
 d=tuple((a+b)/2 for a,b in zip(*ps))
 return geometry('Figure 8.14','Figure 8.14 — center C and the perpendicular from C to chord midpoint D',[path(ellipse(*c,r,r)),path(ps),path([c,d])],[(212,124,'C(−g,−f)'),(160,222,'P(x₁,y₁)'),(336,187,'Q(x₂,y₂)'),(d[0]+5,d[1]+17,'D')],points=[{'x':x,'y':y} for x,y in [c,*ps]],size=(500,280))
def four_chords():
 c=(255,175);r=105
 a,b,d,e=[(c[0]+r*cos(t*pi/180),c[1]+r*sin(t*pi/180)) for t in [190,70,250,10]]
 paths=[path(ellipse(*c,r,r)),path([a,b,e,d,a]),path([(80,300),(80,25)]),path([(55,280),(450,280)])]
 labels=[(77,20,'y'),(456,287,'x'),(61,306,'O'),(c[0]+6,c[1]+7,'C')]
 for p,t in zip([a,b,d,e],'ABDE'):labels.append((p[0]+(-17 if t=='A' else 4),p[1]+(-8 if t=='D' else 17),t))
 for (u,v),t,n in zip([(a,b),(d,e),(a,d),(b,e)],'PQRS',['d₁','d₂','d₃','d₄']):
  mid=tuple((x+y)/2 for x,y in zip(u,v));paths.append(path([c,mid],dash=True));labels.extend([(mid[0]-8,mid[1]-9,t),((c[0]+mid[0])/2+4,(c[1]+mid[1])/2-5,n)])
 return geometry('Figure 8.15','Figure 8.15 — congruent opposite chord pairs AB,DE and AD,BE with their perpendicular center distances',paths,labels,points=[{'x':c[0],'y':c[1]}],size=(500,330))
def equal_chord_coordinates():
 c=(245,175);r=95
 a,b,d,e=(245,80),(150,175),(245,270),(340,175)
 return geometry('Figure 8.16','Figure 8.16 — exact source circle x²+y² = 4 with A(0,2), B(−2,0), D(0,−2), E(2,0)',[path(ellipse(*c,r,r)),path([(110,175),(395,175)]),path([(245,305),(245,45)]),path([a,b]),path([d,e]),path([c,(197.5,127.5)]),path([c,(292.5,222.5)])],[(242,33,'y'),(401,181,'x'),(248,74,'A(0,2)'),(69,186,'B(−2,0)'),(216,295,'D(0,−2)'),(343,170,'E(2,0)'),(250,195,'C'),(204,147,'d₁'),(267,216,'d₂')],points=[{'x':245,'y':175}],size=(480,330))
PAGES=[page('120_page_2.jpg',232,[heading('8.4 Properties of circle'),paragraph('There are some properties of a circle that are listed as under.'),heading('8.4.1 Perpendicular from the center of a circle on a chord bisects the chord'),paragraph('Let the circle be'),eq(r'x^2+y^2+2gx+2fy+c=0','i'),paragraph('and PQ be any chord of a circle, whose end points are P(x₁,y₁) and Q(x₂,y₂) respectively. If PQ is a chord of the circle, then P and Q are the points lying on the circle:'),chord_midpoint(),eq(r'x_1^2+y_1^2+2gx_1+2fy_1+c=0'),eq(r'x_2^2+y_2^2+2gx_2+2fy_2+c=0'),paragraph('The subtraction of these two circle equations gives the slope of the chord PQ:'),eq(r'(x_2^2-x_1^2)+(y_2^2-y_1^2)+2g(x_2-x_1)+2f(y_2-y_1)=0'),eq(r'(x_2^2-x_1^2)+2g(x_2-x_1)+(y_2^2-y_1^2)+2f(y_2-y_1)=0'),eq(r'(x_2-x_1)(x_1+x_2+2g)+(y_2-y_1)(y_1+y_2+2f)=0'),eq(r'\frac{y_2-y_1}{x_2-x_1}=-\frac{x_1+x_2+2g}{y_1+y_2+2f}=m_1,\quad\mathrm{say}','ii'),paragraph('If the center of the circle is C(−g,−f) and the midpoint of the chord PQ is D((x₁+x₂)/2,(y₁+y₂)/2), then the slope of the perpendicular line CD is:'),eq(r'm_2=\frac{(y_1+y_2)/2+f}{(x_1+x_2)/2+g}=\frac{y_1+y_2+2f}{x_1+x_2+2g}','iii'),paragraph('From the Figure 8.14 the chord PQ and the line CD are perpendicular if and only if the product of their slopes equals −1:'),eq(r'm_1m_2=-\frac{x_1+x_2+2g}{y_1+y_2+2f}\cdot\frac{y_1+y_2+2f}{x_1+x_2+2g}=-1'),paragraph('Thus, CD is bisector of the chord PQ.'),heading('Note'),paragraph('The perpendicular bisector of any chord PQ of a circle passes through the center of the circle. This is our second property.'),paragraph('The line joining the two points of the circle that touches the center of the circle is called the diameter of the circle. This diameter acts as the perpendicular bisector to the chord PQ, if the diameter of a circle bisects the chord PQ. This is our third property. The proof is similar to property first, but the graphical view is shown in the Figure 8.14.'),note('The slope proof requires all displayed divisors to be nonzero and a non-diameter chord so C and D are distinct. In all orientations, subtraction of equal squared endpoint distances gives (Q−P)·(D−C) = 0. Thus the line through the center perpendicular to the chord passes through its midpoint; its perpendicular bisector contains the center. If the chord itself is a diameter, D = C and CD does not determine a line, though the perpendicular through C still bisects it. The source’s third-property statement needs a non-diameter chord: a diameter through its midpoint is perpendicular to it. Not every diameter through the center is perpendicular to a diameter-chord.')]),
 page('121_page_1.jpg',233,[heading('Example 15'),paragraph('If A(−3,4) and B(1,5) are the end points of the chord AB of the circle x²+y²+x−5y−2 = 0, then show that (a) the line from the center of the circle is perpendicular to AB, also bisects the chord AB; (b) the line from the center of the circle to the midpoint of the chord AB is perpendicular to the chord AB; (c) the perpendicular bisector CD of the chord AB passes through the center of the given circle.'),heading('Solution'),paragraph('The equation of the circle with center C(−1/2,5/2) is x²+y²+x−5y−2 = 0. If the center of the circle is C(−1/2,5/2) and the midpoint of the chord AB is D(−1,9/2), then the slopes of the chord AB and the perpendicular line CD are respectively:'),eq(r'm_1=\frac{5-4}{1+3}=\frac14,\quad m_2=\frac{9/2-5/2}{-1+1/2}=-4'),paragraph('The chord AB and the line CD are perpendicular if and only if the product of their slopes equals −1:'),eq(r'm_1m_2=\frac14(-4)=-1'),paragraph('Therefore, CD is perpendicular bisector of the chord AB. This result is automatically valid for parts b and c.'),
 heading('8.4.4 Congruent chords of a circle are equidistant from its center and its converse'),paragraph('If the perpendicular distances from the center of a circle to its two chords are equal, then the chords are congruent. Let the circle equation with center C(−g,−f) is:'),eq(r'x^2+y^2+2gx+2fy+c=0','i'),four_chords(),paragraph('If AB and DE are the two chords of the circle (i), then the coordinates of the end points of the chord AB and DE are respectively: A(x₁,y₁), D(x₂,y₂), B(x₃,y₃), E(x₄,y₄). From the Figure 8.15, it is clear that the perpendicular distance d₁ = CP from the center C on the chord AB equals the perpendicular distance d₂ = CQ from C on the chord DE, if and only if the chords AB and DE are with equal lengths:'),eq(r'|AB|=|DE|','ii'),paragraph('Thus, the chords AB and DE are equidistant from C on the circle (i), if and only if d₁ = d₂. In similar manner, the chords AD (join A to D) and BE (join B to E) are congruent chords, if the perpendicular distance d₃ = CR from C on the chord AD equals the perpendicular distance d₄ = CS from C on the chord BE:'),eq(r'd_3=d_4,\quad |AD|=|BE|','iii'),note('The source’s listed coordinate order interleaves A,D,B,E while the chord names are AB,DE; labels are retained without confusing the endpoint pairs. A proof for a circle of radius R uses chord length L = 2√(R²−d²). Equal nonnegative distances d give equal lengths; conversely equal lengths give equal d² and hence equal d. The figure is schematic and shows both congruent opposite chord pairs, not an assertion that every inscribed quadrilateral has congruent opposite sides.')]),
 page('121_page_2.jpg',234,[heading('Example 16'),paragraph('Show that the chords AB and DE are equidistant from the center C(0,0) of the circle x²+y² = 4. The coordinates of the end points of the two chords are A(0,2), B(−2,0), D(0,−2) and E(2,0).'),heading('Solution'),paragraph('The circle equation with center C(0,0) is x²+y² = 4 (v). If AB and DE are the two chords of the circle (i), whose coordinates are respectively A(0,2), B(−2,0), D(0,−2) and E(2,0), then from Figure 8.16, it is clear that the chords AB and DE are with equal length:'),equal_chord_coordinates(),eq(r'AB=(-2-0,0-2),\quad |AB|=\sqrt{(-2)^2+(-2)^2}=2\sqrt2'),eq(r'DE=(2-0,0+2),\quad |DE|=\sqrt{2^2+2^2}=2\sqrt2'),paragraph('Thus, the two chords AB and DE are equal. For equidistant, the procedure is as under: The equations of the chords AB and DE through two-point form of the line are respectively:'),eq(r'\frac{y-y_1}{x-x_1}=\frac{y_2-y_1}{x_2-x_1}'),eq(r'\frac{y-2}{x-0}=\frac{0-2}{-2-0}\ \Rightarrow\ \frac{y-2}x=1\ \Rightarrow\ x-y+2=0'),eq(r'\frac{y+2}{x-0}=\frac{0+2}{2-0}\ \Rightarrow\ \frac{y+2}x=1\ \Rightarrow\ x-y-2=0'),paragraph('The perpendicular distance d₁ from C(0,0) on the chord AB is:'),eq(r'd_1=\frac{|0-0+2|}{\sqrt{1+1}}=\frac2{\sqrt2}'),paragraph('The perpendicular distance d₂ from C(0,0) on the chord DE is:'),eq(r'd_2=\frac{|0-0-2|}{\sqrt{1+1}}=\frac2{\sqrt2}'),paragraph('The perpendicular distance d₁ from C(0,0) on the chord AB is equal to the perpendicular distance d₂ from C(0,0) on the chord DE: d₁ = d₂ = 2/√2. Thus, the chords AB and DE are equidistant from the center C(0,0) of the circle (i).'),
 heading('8.4.5 Measure of the central angle of a minor arc is double the measure of the angle subtended by the corresponding major arc'),paragraph('Let the circle x²+y² = a² (i) and the arc BC is the minor arc of the circle (i), whose coordinates are B(−x₁,−y₁) and C(x₁,−y₁), and the minor arc BC subtended the angle from the center of the circle is ∠BOC. If A(0,a) is a point on the major arc, then join AB and AC that develops the angle of the minor arc which is two times the angle subtended by the major arc:'),eq(r'\angle BOC=2\angle BAC','ii'),note('The inscribed angle BAC has its vertex on the major arc and intercepts the minor arc BC. It is not an angle measuring the major arc itself. For the depicted symmetric arrangement take a > 0 and x₁,y₁ > 0 with x₁²+y₁² = a². The proof continues on the next source page.')])]
for p in PAGES:
 p.update(title='CONICS-I',visualStatus='Full chord/bisector proofs and Examples 15–16, three native figures and central-angle setup',alternateVerification={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':120 if p['page']==232 else 121,'side':'left' if p['page']==233 else 'right','reason':'All source midpoint coordinates, chord signs, perpendicular distances and theorem qualifications checked'})
EXAMPLES=[]
for n,q,steps,ans,p in [
 ('15','For chord A(−3,4), B(1,5) of x²+y²+x−5y−2 = 0, show its center-to-midpoint line is its perpendicular bisector and passes through the center.',['Complete squares: (x+1/2)²+(y−5/2)² = 17/2, so C = (−1/2,5/2).','Both endpoints satisfy the circle: at A, 9+16−3−20−2 = 0; at B, 1+25+1−25−2 = 0.','The midpoint is D = ((−3+1)/2,(4+5)/2) = (−1,9/2).','The chord direction is B−A = (4,1). The center-to-midpoint direction is D−C = (−1/2,2).','Their dot product is 4(−1/2)+1·2 = 0, so the two lines are perpendicular.','D is the midpoint by construction, so the perpendicular center-to-midpoint line bisects the chord, establishing (a) and (b).','Its equation is 4x+y−1/2 = 0, or 8x+2y−1 = 0. Substitution of C and D gives zero, proving that this perpendicular bisector passes through the center as requested in (c).'],'Perpendicular bisector 8x+2y−1 = 0 through C(−1/2,5/2) and D(−1,9/2).',233),
 ('16','Show chords AB and DE of x²+y² = 4 with A(0,2), B(−2,0), D(0,−2), E(2,0) are equidistant from C(0,0).',['Each endpoint has squared norm 4, so all four lie on the circle.','Chord AB has direction (−2,−2), length 2√2 and line equation x−y+2 = 0.','Chord DE has direction (2,2), length 2√2 and line equation x−y−2 = 0.','The center-to-AB distance is |2|/√2 = √2.','The center-to-DE distance is |−2|/√2 = √2, proving equidistance.','As a geometric check, the chord midpoints are (−1,1) and (1,−1); each has distance √2 from C and is the perpendicular foot.','The common circle radius is 2, and the chord formula 2√(4−2) = 2√2 reproduces both chord lengths.'],'Both perpendicular distances are √2; both chord lengths are 2√2.',234)]:
 EXAMPLES.append({'num':n,'title':'Circle Chord Properties','question':q,'steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':p,'jpg':'121_page_1.jpg' if p==233 else '121_page_2.jpg','verification':'Complete source endpoint coordinates, midpoint and distances checked'}],**({'sourceQuestionBlocks':[equal_chord_coordinates()]} if n=='16' else {})})
